INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('taiping','太平天国','["太平天国","太平天囯","天囯"]',NULL,NULL,'cn','east_asia',1851,3,NULL,'month',1864,7,NULL,'month',22214,22374,'ochre',NULL,NULL,'洪秀全、冯云山等以拜上帝会组织广西部众，1851年金田起义后建号太平天国，洪秀全随后在武宣称天王。1853年攻取南京、改称天京并定都；天京事变及清军进攻削弱其统治，1864年7月19日天京陷落。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hong-tianguifu','洪天贵福','taiping','[]',NULL,NULL,1849,11,NULL,'month',1864,11,NULL,'month','["皇帝"]','洪秀全长子，幼天王；洪秀全死后于六月初六继位，天京陷落后被俘处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/洪天贵福"}]',NULL,NULL,'幼天王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hong-xiuquan','洪秀全','taiping','[]',NULL,NULL,1814,1,NULL,'year',1864,6,NULL,'month','["皇帝","起义领袖"]','广东花县人，早年应试未中。1843年创立拜上帝会，次年与冯云山赴广西传教；冯云山等在紫荆山区组织会众，逐渐形成武装力量。1851年金田起义，建立太平天国，洪秀全称天王；1853年攻取南京，改名天京并定都。1856年天京事变使领导层分裂，1864年在天京病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/洪秀全"}]',NULL,NULL,'天王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xiucheng','李秀成','taiping','[]',NULL,NULL,1823,1,NULL,'year',1864,8,NULL,'month','["军事家","政治家"]','太平天国忠王，后期主持军政；同治三年七月初六（1864年8月7日）城破后被俘处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李秀成"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-dakai','石达开','taiping','[]',NULL,NULL,1831,1,NULL,'year',1863,6,NULL,'month','["军事家"]','太平天国翼王，西征名将；咸丰七年出走后转战西南，同治二年五月初十（1863年6月10日）大渡河兵败被俘。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石达开"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-xiuqing','杨秀清','taiping','[]',NULL,NULL,1823,1,NULL,'year',1856,9,NULL,'month','["政治家","军事家"]','太平天国东王，定都天京后掌军政大权；咸丰六年八月初四（1856年9月2日）天京事变中被北王韦昌辉所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨秀清"}]',NULL,NULL,NULL,'[]');
