INSERT INTO "reigns" ("id","dynasty_id","person_id","title","era_names","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","claim_track","is_informal_monarch","is_main") VALUES ('reign-hong-xiuquan-taiping','taiping','hong-xiuquan','',NULL,1851,3,23,'day',1864,6,1,'day',22214,22373,NULL,0,0);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('fall-of-tianjing','天京陷落','battle','point','day',NULL,NULL,'同治三年六月十六日，1864年7月19日',1864,7,19,22374,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'曾国荃所部湘军攻陷天京，太平天国政权败亡；洪天贵福出逃后被俘，余部仍继续作战。',NULL,NULL,'[{"label":"中国国家博物馆：金田起义","url":"https://www.chnmuseum.cn/zp/zpml/ysp/202012/t20201214_248369.shtml"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('hong-tianguifu-captured','幼天王被俘','politics','point','day',NULL,NULL,'同治三年九月二十二日，1864年10月25日，江西石城',1864,10,25,22377,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'湘军追擒幼天王洪天贵福于江西石城，太平天国余绪终结。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('hong-xiuquan-enthroned','洪秀全秘密称王','politics','point','approximate_year',NULL,NULL,'中国社会科学院夏春涛据《天兄圣旨》考释：洪秀全约在己酉年冬（1849）秘密称王，随后逐步公开称王建号；登极是过程，具体日期难定。传统所称1851年3月23日据后设纪念日推定，不能作为确切登极日。',1849,12,NULL,22199,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'洪秀全在起义筹备期间已于紫荆山区秘密称王，后来逐步公开称号并建号；称王与登极是演变过程，不能确定为单一日。',NULL,NULL,'[{"label":"中国社会科学院：洪秀全登极暨金田起义时间考释","url":"https://www.cass.cn/xueshuchengguo/makesizhuyixuebu/201403/t20140324_1040392.shtml"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('jintian-uprising','金田起义','politics','point','approximate_day',NULL,NULL,'通行纪念日期为道光三十年十二月初十（公历1851年1月11日）；夏春涛考释指出起义是逐步展开的过程，具体起义日存在异说，此点采用通行纪念日作近似定位。',1851,1,11,22212,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'洪秀全、杨秀清等在广西桂平金田发动反清武装起义，建立太平天国；起义前后经历团营、交战和公开建号，具体起事日有史料异说。',NULL,NULL,'[{"label":"中国社会科学院：洪秀全登极暨金田起义时间考释","url":"https://www.cass.cn/xueshuchengguo/makesizhuyixuebu/201403/t20140324_1040392.shtml"},{"label":"中国国家博物馆：金田起义","url":"https://www.chnmuseum.cn/zp/zpml/ysp/202012/t20201214_248369.shtml"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('taiping-capital-tianjing','定都天京','politics','point','day',NULL,NULL,'咸丰三年二月初十（公历1853年3月19日），太平军攻占江宁并定都；洪秀全入城时间不作为另一个日期。',1853,3,19,22238,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'太平军攻占江宁，洪秀全定都于此并改称天京，建立与清廷长期对峙的政权。',NULL,NULL,'[{"label":"中国国家博物馆：金田起义","url":"https://www.chnmuseum.cn/zp/zpml/ysp/202012/t20201214_248369.shtml"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('tianjing-incident','天京事变','politics','point','day',NULL,NULL,'咸丰六年八月初四，1856年9月2日东王杨秀清被诛',1856,9,2,22280,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'韦昌辉奉洪秀全命在天京杀死东王杨秀清，随后清洗东王部众；事变重创太平天国领导层，石达开出走。',NULL,NULL,'[{"label":"中国社会科学院：洪秀全登极暨金田起义时间考释","url":"https://www.cass.cn/xueshuchengguo/makesizhuyixuebu/201403/t20140324_1040392.shtml"}]');
